'use strict';
let nasaData=null,selectedSite=0,nasaPending=null,nasaError='',preparingNASA=false;
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function missionEnvironment(){if(!nasaData)return null;return JSON.parse(JSON.stringify({site:nasaData.sites[selectedSite],eventPool:nasaData.events,retrievedAt:nasaData.retrievedAt,mode:nasaData.mode,donki:nasaData.donki||null,science:nasaData.science||null}))}

const setup=document.createElement('button');setup.id='nasaSetup';setup.textContent='⌖ Prepare mission · NASA APIs';$('start').after(setup);setup.onclick=()=>environmentScreen(true);
const apiBanner=document.createElement('p');apiBanner.id='apiBanner';setup.after(apiBanner);
const envButton=document.createElement('button');envButton.id='environment';envButton.textContent='⌖ Lunar environment and NASA data';$('science').before(envButton);envButton.onclick=()=>environmentScreen(false);
$('dialog').addEventListener('close',()=>{if(!$('dialog').open)preparingNASA=false});
function connectionText(){if(nasaPending)return 'Contacting DONKI, Horizons, Diviner and OSDR…';if(nasaError)return nasaError;if(nasaData?.mode==='online')return `NASA connected · ${nasaData.events.length} DONKI events · Diviner ${nasaData.science?.diviner?.status==='online'?'online':'unavailable'} · OSDR ${nasaData.science?.osdr?.status==='online'?'online':'unavailable'}  · checked at ${new Date(nasaData.retrievedAt).toLocaleTimeString()}`;if(nasaData)return 'Offline mode · 2024 archive';return 'Waiting for NASA data';}
function updateConnection(){apiBanner.textContent=connectionText();$('start').disabled=!!nasaPending||!nasaData;if($('nasaStatus')&&preparingNASA)$('nasaStatus').textContent=connectionText();}
async function refreshNASA(){if(nasaPending)return nasaPending;nasaError='';nasaPending=(async()=>{try{const [r,science]=await Promise.all([fetch('/api/nasa',{cache:'no-store',signal:AbortSignal.timeout(95000)}),fetchScience()]);if(!r.ok)throw Error();const d=await r.json();if(!validNASA(d))throw Error();d.science=science;const siteId=nasaData?.sites[selectedSite]?.id;nasaData=d;selectedSite=Math.max(0,d.sites.findIndex(s=>s.id===siteId));}catch{nasaError='NASA data could not be loaded. Retry or choose the offline archive.';if(nasaData)nasaError+='  The last successful response is still selected.'}finally{nasaPending=null;updateConnection();if(preparingNASA&&$('dialog').open)environmentScreen(true)}})();updateConnection();if(preparingNASA)environmentScreen(true);return nasaPending;}
function chooseOffline(){nasaData=JSON.parse(JSON.stringify(NASA_SNAPSHOT));nasaData.mode='offline';selectedSite=0;nasaError='';updateConnection();environmentScreen(true)}
function landingSiteName(site){
 return site.id==='este'?'Aurora East · training sector':site.name;
}
function updateNASA(){const t=sky(state);envButton.textContent=t?'⌖ '+landingSiteName(state.environment.site).split(' · ')[0]+' · NASA':'⌖ Environment · legacy mission';const e=currentCrisis(state);if(e)$('event').textContent+=' · DONKI '+e.classType+' · '+e.date.slice(0,10);}
function crisisNotice(){const e=currentCrisis(state);if(!e){notify(state.log[0]);return}beep();open(`<small>INCOMING ALERT · DAY ${state.day}</small><h2>Solar activity detected</h2><div class="cost">DONKI ${esc(e.classType)} · ${esc(e.id)}</div><p>Communications are degraded. Shelter the crew and check your reserves. Use high power to transmit during the storm.</p><p>Until the end of the day, panel output is capped at ${solarProfile(state).health}% and crew outside shelter face higher exposure. This scenario recreates a NASA record observed on ${esc(e.date)}.</p><p><a href="${esc(e.url)}" target="_blank" rel="noopener">View NASA record ↗</a></p><button data-close class="primary">Respond to the alert</button>`)}

function mapMarkup(site,offline){if(offline)return `<div class="moonmap"><img src="assets/moon-0.jpg" alt="Western lunar archive map"><img src="assets/moon-1.jpg" alt="Eastern lunar archive map"><span style="left:${(site.lon+180)/360*100}%;top:${(90-site.lat)/180*100}%">✦</span></div><p>Offline global map.</p>`;const gx=(site.lon+180)/5.625,gy=(90-site.lat)/5.625,x=Math.floor(gx),y=Math.floor(gy);let imgs='';for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)imgs+=`<img src="/api/moon-tile?x=${x+dx}&y=${y+dy}" alt="Lunar tile ${x+dx}, ${y+dy}" draggable="false">`;return `<div class="moonLocal"><div class="moonTiles">${imgs}<span class="baseMarker" style="left:${(gx-x+1)/3*100}%;top:${(gy-y+1)/3*100}%">✦<b>${esc(landingSiteName(site).split(' · ')[0])}</b></span></div></div><p id="mapStatus" role="status">Moon Trek WMTS · regional view 16.875° × 16.875° · north up. Loading NASA tiles…</p>`;}
function wireMap(){const imgs=[...document.querySelectorAll('.moonTiles img')],status=$('mapStatus');if(!status)return;const update=()=>{if(imgs.some(i=>i.dataset.failed))status.textContent='Moon Trek could not load every tile for this region.';else if(imgs.every(i=>i.complete&&i.naturalWidth))status.textContent='Moon Trek · 9 regional tiles loaded. Historical LRO WAC mosaic.'};imgs.forEach(i=>{i.onload=update;i.onerror=()=>{i.dataset.failed='1';update()}});update();}
function auditMarkup(env,known=[]){if(!env.donki)return '<p>This mission uses the local historical archive.</p>';const a=env.donki;return `<div class="apiProof" id="donkiProof"><b>DONKI · HTTP ${a.httpStatus}</b><br>Queried: ${esc(a.queriedAt)}<br>Requested period: ${esc(a.range.start)} → ${esc(a.range.end)}<br>NASA returned ${a.receivedCount}  records.${a.acceptedCount}  C/M/X events are usable.<br>Access: ${esc(a.authentication)}<br><a href="${esc(a.sourceURL)}" target="_blank" rel="noopener">Endpoint and query dates ↗</a></div><details><summary>View DONKI records for detected events (JSON)</summary><pre>${esc(JSON.stringify(a.records.filter(r=>known.some(c=>c.event.id===r.flrID)),null,2))}</pre></details>`;}
function environmentScreen(configure=false){preparingNASA=configure;const env=configure?missionEnvironment():state.environment;
 if(!env){open(`<h2>${configure?'Connect mission to NASA':'Saved legacy mission'}</h2><p id="nasaStatus" role="status">${configure?esc(connectionText()):'Start a new mission to use the NASA APIs.'}</p><div class="buttons">${configure?`<button id="syncNASA" ${nasaPending?'disabled':''}>Retry connection</button><button id="offlineNASA" ${nasaPending?'disabled':''}>Use offline mode (2024 archive)</button>`:''}<button data-close>Back</button></div>`);if(configure){$('syncNASA').onclick=refreshNASA;$('offlineNASA').onclick=chooseOffline}return}
 const site=env.site,t=site.turns[configure?0:(state.day-1)%site.turns.length],known=configure?[]:encounteredCrises(state);
 open(`<small>MISSION CONTROL / NASA APIs</small><h2>${configure?'Prepare expedition':'Lunar environment and data sources'}</h2><p id="nasaStatus" role="status">${configure?esc(connectionText()):esc(env.mode==='online'?'API data retrieved for this mission · '+env.retrievedAt:'Local archive selected · '+env.retrievedAt)}</p>
 ${configure?`<label>Landing site <select id="siteChoice" ${nasaPending?'disabled':''}>${nasaData.sites.map((s,i)=>`<option value="${i}" ${i===selectedSite?'selected':''}>${esc(landingSiteName(s))}</option>`).join('')}</select></label>`:''}
 <p class="cost">☀ Solar monitoring is active. One or two unexpected events may occur during the expedition.${env.donki?' · <a href="#donkiProof">View DONKI connection ↓</a>':''}</p>
 <h3>${esc(landingSiteName(site))} · ${site.lat}° N / ${site.lon}° E</h3>${mapMarkup(site,env.mode!=='online')}
 <p class="muted">LRO WAC · NASA/GSFC/Arizona State University, via Moon Trek. The fictional base uses real coordinates and terrain. Solar events are revealed during gameplay.</p>
 <h3>Detected events</h3>${known.length?known.map(c=>`<div class="cost">Day ${c.turn} · DONKI ${esc(c.event.classType)} · ${esc(c.event.id)}<br>Observed: ${esc(c.event.date)} · <a href="${esc(c.event.url)}" target="_blank" rel="noopener">NASA record ↗</a></div>`).join(''):'<p>No events detected yet. Keep energy in reserve and prepare shelters.</p>'}<p>Solar events use records from DONKI. Their timing and effects on the base are simulated. If the catalog has no usable records, the game schedules no DONKI events.</p>
 ${auditMarkup(env,known)}${scienceMarkup(env)}
 <h3>Geometry calculated by Horizons</h3><div class="cost">Reference date: ${esc(t.date)}<br>Sun azimuth ${t.sun.az.toFixed(2)}° · elevation ${t.sun.el.toFixed(2)}°<br>Earth azimuth ${t.earth.az.toFixed(2)}° · elevation ${t.earth.el.toFixed(2)}°<br>${t.sun.el>0?'Sun above the horizon':'Night: no solar generation'}</div>
 <p>Horizons supplies reference geometry for May 17 through June 10, 2024, with three daylight phases and four night phases. The game recreates events from the last 30 days of DONKI records on that training schedule.</p>
 <p>Set the elevation of the panels and antenna while azimuth adjusts automatically. In the antenna exercise, Earth follows a simulated arc and wraps at the edge. Saving the locked alignment applies the calibration to the Horizons reference. Earth reception windows are phases 2, 4 and 6.</p>
 <p class="muted">Each day lasts three minutes. After seven reference phases, the game repeats the geometry and replays the recorded solar events. Difficulty increases every three days.</p><div class="nasaTurns">${site.turns.map((r,i)=>`<span>${i+1} · ${r.date.slice(5,10)}<br>${r.sun.el>0?'☀ Day':'☾ Night'}${known.some(c=>c.turn===i+1)?'<br>⚠ DONKI':''}</span>`).join('')}</div>
 <p><a href="https://trek.nasa.gov/moon/" target="_blank" rel="noopener">Moon Trek</a> · <a href="${esc(site.sources[0])}" target="_blank" rel="noopener">Sun query</a> · <a href="${esc(site.sources[1])}" target="_blank" rel="noopener">Earth query</a></p>
 <div class="buttons">${configure?`<button id="syncNASA" ${nasaPending?'disabled':''}>Refresh API data</button><button id="launchNASA" class="primary" ${nasaPending?'disabled':''}>Launch expedition</button>`:'<button id="guideSources">Guide and life support</button>'}<button data-close>${configure?'Save setup':'Return to base'}</button></div>`);
 wireMap();if(!configure)$('guideSources').onclick=originalScientific;
 if(configure){$('siteChoice').onchange=e=>{selectedSite=Number(e.target.value);environmentScreen(true)};$('syncNASA').onclick=refreshNASA;$('launchNASA').onclick=()=>{close();start()};}
}
async function fetchScience(){try{const r=await fetch('/api/science',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const d=await r.json();if(d.version!==1||!['online','unavailable'].includes(d.diviner?.status)||!['online','unavailable'].includes(d.osdr?.status))throw Error();return d}catch{return {diviner:{status:'unavailable'},osdr:{status:'unavailable'},error:'Science data unavailable. Retry from Prepare mission.'}}}
function scienceMarkup(env){
 const d=env.science?.diviner,o=env.science?.osdr,cell=d?.cells?.find(c=>c.siteId===env.site.id);
 const curve=cell?cell.curve.map(p=>`${(p.hour/24*560+20).toFixed(1)},${(130-(p.kelvin-cell.minK)/(cell.maxK-cell.minK)*100).toFixed(1)}`).join(' '):'';
 return `<section class="scienceData"><h3>Diviner / thermal control</h3>${d?.status==='online'&&cell?`<div class="thermalChart"><svg viewBox="0 0 600 160" role="img" aria-label="Mean bolometric temperature by local solar time"><path d="M20 20V130H580" fill="none" stroke="#54718c"/><polyline points="${curve}" fill="none" stroke="#efb76b" stroke-width="3"/><text x="20" y="153">0 h</text><text x="280" y="153">12 h</text><text x="545" y="153">24 h</text></svg></div><p>Observed range: <b>${(cell.minK-273.15).toFixed(1)}  to ${(cell.maxK-273.15).toFixed(1)} °C</b>  · cell ${cell.lat}° N / ${cell.lon}° E · ${cell.curve.length}/96 valid samples.</p><p>PDS HTTP 206 retrieves only the rows for this cell. Historical mean bolometric surface temperatures for ${esc(d.observations)}, resolution ${esc(d.resolution)}. Values describe the surface.</p><p>The game estimates surface temperature from the curve's extremes and the solar elevation from Horizons. Cabin temperatures, costs and effects are simulated.</p><a href="${esc(d.sourceURL)}" target="_blank" rel="noopener">Diviner PDS table ↗</a> · <a href="${esc(d.labelURL)}" target="_blank" rel="noopener">Dataset and units ↗</a>`:'<p>Diviner is unavailable in this mission. Night heating uses 14 energy per day. Reconnect and start a new mission to use Diviner data.</p>'}
 <h3>OSDR / plant experiment</h3>${o?.status==='online'?`<p><b>${esc(o.id)} · ${esc(o.project)}</b><br>${esc(o.title)}</p><div class="cost">${o.lightHours}  h light  / ${o.darkHours}  h dark · ${o.lightIntensity} µmol/m²/s<br>Recorded mean temperature: ${o.temperatureC} °C · sample harvest: ${o.harvestDays}  days<br>${esc(o.hardware)} · ${esc(o.platform)}</div><p>This study compared the microbiology and nutrition of lettuce grown on the ISS with lettuce grown on Earth. The game compresses growth time and simulates the yield and rewards.</p><p>Plant and water an experiment, then apply the OSDR protocol. Keep the temperature within 3 °C of the reference for two days of growth. Harvest to earn 10 extra science and data and reduce later watering costs to 5 water.</p><a href="${esc(o.studyURL)}" target="_blank" rel="noopener">OSD-267 study ↗</a> · <a href="${esc(o.sourceURL)}" target="_blank" rel="noopener">Metadata API ↗</a> · <a href="${esc(o.assaysURL)}" target="_blank" rel="noopener">Sample conditions (CSV) ↗</a>`:'<p>OSDR is unavailable in this mission. Standard crops are available.</p>'}
 <p class="muted">Queried: ${esc(env.science?.queriedAt||'no successful query')}. The data is saved with the mission. Both services are public.</p></section>`;
}
function scienceModuleMarkup(key){
 const h=thermal(state),o=studyData(state);if(!['life','power','food'].includes(key))return '';
 const thermalCard=h?`<div class="thermalCard"><b>THERMAL CONTROL · DIVINER</b><div class="thermalStats"><span>ESTIMATED SURFACE<strong>${h.exteriorC.toFixed(0)} °C</strong></span><span>CURRENT CABIN<strong>${h.cabinC.toFixed(1)} °C</strong></span><span>ENERGY PER DAY<strong>${h.cost} energy</strong></span></div><p>Mode ${h.mode==='auto'?'automatic':h.mode==='eco'?'eco':'off'} · target ${h.setpoint} °C · insulation ${state.insulation?'installed':'pending'}. Thermal control draws power continuously and takes priority over life support and crops.</p>${key!=='life'?'<button id="thermalControls">Manage temperature in Life Support</button>':''}</div>`:'<p class="muted">Diviner unavailable · night heating uses 14 energy per day.</p>';
 return thermalCard+(key==='food'?`<div class="thermalCard"><b>PLANT SCIENCE · ${o?'OSD-267':'OSDR OFFLINE'}</b><p>${o?`${o.lightHours} / ${o.darkHours} h light/dark · ${o.temperatureC} °C recorded · ${o.lightIntensity} µmol/m²/s. Study conducted on the ISS.`:'Start a connected expedition to use the OSDR protocol.'}</p>${o?`<p>Experiment validation: ${Math.min(2,state.crop?.protocolTurns||0)}/2 days. Improved irrigation: ${state.irrigationUpgrade?'active (5 water)':'pending'}. Apply the OSD-267 protocol to a planted experiment. Keep it watered and at the target temperature.</p>`:''}</div>`:'')+'<button id="scienceProvenance">View NASA data and sources</button>';
}
function validNASA(d){return d?.version===2&&d.mode==='online'&&d.sites?.length===2&&Array.isArray(d.events)&&d.donki?.httpStatus===200&&Array.isArray(d.donki.records)&&d.sites.every(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lon)&&s.turns?.length===7&&s.sources?.every(u=>u.startsWith('https://ssd.jpl.nasa.gov/'))&&s.turns.every(t=>['sun','earth','earthNext'].every(k=>Number.isFinite(t[k]?.el)&&Math.abs(t[k].el)<=90&&Number.isFinite(t[k].az))))&&d.events.every(e=>/^https:\/\/ccmc\.gsfc\.nasa\.gov\/DONKI\//.test(e.url)&&/^[CMX]\d+(\.\d+)?$/.test(e.classType))}
const originalScientific=scientific;
scientific=function(){if(state.environment)environmentScreen(false);else originalScientific()};$('science').onclick=scientific;
// Normal mode always requests the APIs; bundled data is opt-in only.
refreshNASA();
